class BrokenSpin {
    volatile int curr = 1;
    final int n;
    BrokenSpin(int n) { this.n = n; }
    // WRONG: check-then-act races, sleep is not coordination.
    public void fizz(Runnable printFizz) {
        while (curr <= n) {
            if (curr % 3 == 0 && curr % 5 != 0) {
                printFizz.run(); // two threads can enter here
                curr++;          // lost update, duplicate, skip
            } else {
                try { Thread.sleep(1); } catch (InterruptedException e) { return; }
            }
        }
    }
}

