class FizzBuzz {
    private final int n;
    private int curr = 1; // guarded by this

    public FizzBuzz(int n) {
        this.n = n;
    }

    // Only the thread whose predicate matches curr may consume it.
    // Every state change uses notifyAll: simple, no missed signal.
    public synchronized void fizz(Runnable printFizz) throws InterruptedException {
        while (curr <= n) {
            if (curr % 3 == 0 && curr % 5 != 0) {
                printFizz.run();
                curr++;
                notifyAll();
            } else {
                wait();
            }
        }
    }

    public synchronized void buzz(Runnable printBuzz) throws InterruptedException {
        while (curr <= n) {
            if (curr % 5 == 0 && curr % 3 != 0) {
                printBuzz.run();
                curr++;
                notifyAll();
            } else {
                wait();
            }
        }
    }

    public synchronized void fizzbuzz(Runnable printFizzBuzz) throws InterruptedException {
        while (curr <= n) {
            if (curr % 3 == 0 && curr % 5 == 0) {
                printFizzBuzz.run();
                curr++;
                notifyAll();
            } else {
                wait();
            }
        }
    }

    public synchronized void number(Runnable printNumber) throws InterruptedException {
        while (curr <= n) {
            if (curr % 3 != 0 && curr % 5 != 0) {
                printNumber.run();
                curr++;
                notifyAll();
            } else {
                wait();
            }
        }
    }
}

import threading

class FizzBuzz:
    def __init__(self, n: int):
        self.n = n
        self.curr = 1
        self.cond = threading.Condition()

    def _run(self, pred, action):
        while True:
            with self.cond:
                while self.curr <= self.n and not pred(self.curr):
                    self.cond.wait()
                if self.curr > self.n:
                    self.cond.notify_all()  # wake stragglers so join() ends
                    return
                action()
                self.curr += 1
                self.cond.notify_all()

    def fizz(self, printFizz):
        self._run(lambda x: x % 3 == 0 and x % 5 != 0, printFizz)

    def buzz(self, printBuzz):
        self._run(lambda x: x % 5 == 0 and x % 3 != 0, printBuzz)

    def fizzbuzz(self, printFizzBuzz):
        self._run(lambda x: x % 3 == 0 and x % 5 == 0, printFizzBuzz)

    def number(self, printNumber):
        self._run(lambda x: x % 3 != 0 and x % 5 != 0, printNumber)
